//! Two independent hunks make the Git index observable during practice.

pub(crate) const BASE: &str = "fn add_score(score: u32, points: u32) -> u32 {\n    score - points\n}\n\n// Keep the scoring fix separate from presentation work.\n// A commit should tell one clear story.\n// The lines between these functions keep their changes\n// in separate Git hunks.\n// Review both before deciding what belongs together.\n// Nothing in this repository will be pushed.\n\nfn title() -> &'static str {\n    \"Practice mode\"\n}\n";
pub(crate) const INDEX: &str = "fn add_score(score: u32, points: u32) -> u32 {\n    score + points\n}\n\n// Keep the scoring fix separate from presentation work.\n// A commit should tell one clear story.\n// The lines between these functions keep their changes\n// in separate Git hunks.\n// Review both before deciding what belongs together.\n// Nothing in this repository will be pushed.\n\nfn title() -> &'static str {\n    \"Practice mode\"\n}\n";
pub(crate) const WORKTREE: &str = "fn add_score(score: u32, points: u32) -> u32 {\n    score + points\n}\n\n// Keep the scoring fix separate from presentation work.\n// A commit should tell one clear story.\n// The lines between these functions keep their changes\n// in separate Git hunks.\n// Review both before deciding what belongs together.\n// Nothing in this repository will be pushed.\n\nfn title() -> &'static str {\n    \"Scoreboard\"\n}\n";
